SELECT COUNT(*)
FROM schedule_shifts ss
WHERE ss.worker_id = #{workerId}

    AND ss.shift_date >= #{startDate}


    AND ss.shift_date <= #{endDate}

SELECT ss.*
FROM schedule_shifts ss
WHERE ss.worker_id = #{workerId}
  AND ss.shift_date = #{date}
  AND ss.status != 'CANCELLED'
ORDER BY ss.start_time ASC

SELECT ss.*
FROM schedule_shifts ss
WHERE ss.worker_id = #{workerId}
  AND ss.shift_date > #{date}
  AND ss.status != 'CANCELLED'
ORDER BY ss.shift_date ASC, ss.start_time ASC
LIMIT #{size}

SELECT ss.*
FROM schedule_shifts ss
WHERE ss.job_id = #{jobId}

